(2350222, 324614, 32885, '<td valign="top">I love this image. The depth and colour contrasts are very good IMHO.</td>', 'I love this image. The depth and colour contrasts are very good IMHO.', '2006-04-27 10:39:41.000000', NULL, 1),
(2350226, 324110, 32885, '<td valign="top">A very intriguing image. Well done.</td>', 'A very intriguing image. Well done.', '2006-04-27 10:41:12.000000', NULL, 1),
