(2361882, 325061, 33392, '<td valign="top">How did you pull this off?  Nice idea and well composed.</td>', 'How did you pull this off?  Nice idea and well composed.', '2006-04-30 10:54:35.000000', NULL, 1),
(2361886, 324902, 33392, '<td valign="top">This is very well composed and well lit.  Understated at its best.</td>', 'This is very well composed and well lit.  Understated at its best.', '2006-04-30 10:54:55.000000', NULL, 1),
