(2363878, 325071, 54731, '<td valign="top">A little  bit too dark but nice expression on his face.</td>', 'A little  bit too dark but nice expression on his face.', '2006-04-30 18:35:32.000000', NULL, 1),
(2363882, 324511, 29753, '<td valign="top">very nice. it feels very dull</td>', 'very nice. it feels very dull', '2006-04-30 18:35:40.000000', NULL, 1),
