(2363887, 324425, 29753, '<td valign="top">i like the softness</td>', 'i like the softness', '2006-04-30 18:35:54.000000', NULL, 1),
(2363889, 324076, 27845, '<td valign="top">It was a good decision to use selective desaturation for this photograph. The flowers might not have come out well enough otherwise. You might have desaturated the plants in the upper part of the window as well though, since they''re not something you''d want attention to be drawn on.</td>', 'It was a good decision to use selective desaturation for this photograph. The flowers might not have come out well enough otherwise. You might have desaturated the plants in the upper part of the window as well though, since they''re not something you''d want attention to be drawn on.', '2006-04-30 18:35:59.000000', NULL, 1),
(2363893, 323718, 54731, '<td valign="top">THis one''s really nice, black and white works well.</td>', 'THis one''s really nice, black and white works well.', '2006-04-30 18:36:18.000000', NULL, 1),
(2363895, 323686, 29753, '<td valign="top">amazing picture! should score very well i like the contrast</td>', 'amazing picture! should score very well i like the contrast', '2006-04-30 18:36:27.000000', NULL, 1),
(2363896, 323718, 29753, '<td valign="top">cool tones</td>', 'cool tones', '2006-04-30 18:36:40.000000', NULL, 1),
